namespace MentorRecorder.Collector.Domain.Mutations;

/// <summary>Request to add a character profile to a region.</summary>
/// <param name="RequestId">Idempotency key generated by the client.</param>
/// <param name="Region">Region the character plays in.</param>
/// <param name="DisplayName">Name the player typed; 1 to 24 characters after trimming.</param>
/// <param name="GoalCount">Target completions; at least 1.</param>
/// <param name="BaselineCompletedCount">Completions the character had before it was recorded here.</param>
/// <param name="MakeCurrent">Whether newly recorded runs are filed under it from now on.</param>
public sealed record CreateCharacterProfileCommand(
    string RequestId,
    Region Region,
    string DisplayName,
    int GoalCount,
    int BaselineCompletedCount,
    bool MakeCurrent,
    long? IdentityId = null);

/// <summary>Request to rename a character profile, to make it the current one of its region, or both.</summary>
/// <param name="RequestId">Idempotency key generated by the client.</param>
/// <param name="ProfileId">Profile to change.</param>
/// <param name="DisplayName">New name, or null to keep the name.</param>
/// <param name="MakeCurrent">True to file newly recorded runs under this profile from now on.</param>
public sealed record UpdateCharacterProfileCommand(
    string RequestId,
    long ProfileId,
    string? DisplayName,
    bool MakeCurrent,
    bool ForgetIdentities = false);

/// <summary>Request to remove a character profile no run belongs to.</summary>
/// <param name="RequestId">Idempotency key generated by the client.</param>
/// <param name="ProfileId">Profile to remove.</param>
public sealed record DeleteCharacterProfileCommand(string RequestId, long ProfileId);

/// <summary>Outcome of a character profile change.</summary>
/// <param name="Profile">The profile as stored after the change; null after a deletion.</param>
/// <param name="ProfileId">Profile the request addressed or created.</param>
/// <param name="Region">Region of that profile.</param>
/// <param name="IdempotentReplay">True when this replays an earlier request with the same id.</param>
public sealed record CharacterProfileOutcome(
    CharacterProfile? Profile,
    long ProfileId,
    Region Region,
    bool IdempotentReplay);
